"""Optional natural-language summary via a local Ollama model.

Safety design:
* The model receives ONLY the pre-computed findings text - no raw data, no tools.
* It is told to use no other numbers or medical claims.
* Its output is validated: every number it writes must appear in the findings. If any number
  is invented, the summary is discarded and the deterministic template text is returned.
* Output is always labelled AI-generated by the API/UI.
"""
from __future__ import annotations

import re

import httpx

from .config import settings

_PERSIAN = str.maketrans("۰۱۲۳۴۵۶۷۸۹٫٬", "0123456789.,")
_NUM = re.compile(r"\d+(?:[.,]\d+)*")


def _numbers(text: str) -> set[str]:
    out = set()
    for m in _NUM.findall(text.translate(_PERSIAN)):
        m = m.replace(",", "")
        out.add(m)
        try:
            out.add(f"{float(m):g}")
        except ValueError:
            pass
    return out


def validate(summary: str, source_text: str) -> bool:
    allowed = _numbers(source_text)
    return all(n in allowed for n in _numbers(summary))


def build_prompt(lines: list[str], lang: str) -> str:
    language = "Persian (Farsi)" if lang == "fa" else "English"
    joined = "\n".join(f"- {l}" for l in lines)
    return (
        f"You are assisting physicians reading epidemiological statistics. Write a concise "
        f"summary (3-4 sentences) in {language} of the findings below.\n"
        "STRICT RULES: use ONLY facts and numbers that appear in the findings; do not add any "
        "other number, cause, recommendation, diagnosis or treatment; keep every caveat about "
        "data quality; do not speculate about reasons.\n\nFINDINGS:\n" + joined
    )


async def narrate(findings: list[dict], lang: str) -> dict:
    lines = [f["text_fa" if lang == "fa" else "text_en"] for f in findings]
    fallback = " ".join(lines)
    try:
        async with httpx.AsyncClient(timeout=settings.ollama_timeout_s) as client:
            r = await client.post(
                f"{settings.ollama_url}/api/generate",
                json=dict(model=settings.ollama_model, prompt=build_prompt(lines, lang),
                          stream=False, options=dict(temperature=0.1)),
            )
            r.raise_for_status()
            text = (r.json().get("response") or "").strip()
    except Exception as e:  # noqa: BLE001
        return dict(text=fallback, ai_generated=False, validated=True,
                    note=f"LLM unavailable ({type(e).__name__}); showing template text.")
    if not text or not validate(text, " ".join(lines)):
        return dict(text=fallback, ai_generated=False, validated=False,
                    note="LLM output failed number validation; showing template text.")
    return dict(text=text, ai_generated=True, validated=True, model=settings.ollama_model)
